<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue'
import RichText from './RichText.vue'
import DetailDialog from './DetailDialog.vue'
import { answered, type TaskAnswers, type TaskQuestion } from '../assessments'
import { useViewMemory } from '../viewMemory'
const props=defineProps<{id:string;questions:TaskQuestion[];answers:TaskAnswers;submitted:boolean;graded:boolean;busy:boolean;canSubmit:boolean;message:string;aiPolicy?:string}>()
const emit=defineEmits<{'update:answers':[value:TaskAnswers];submit:[];assist:[id:string]}>()
const memory=useViewMemory(), memoryKey=JSON.stringify([memory?.owner(),props.id,'assignment-position'])
const remembered=memory?.values.get(memoryKey)
const firstUnanswered=props.questions.findIndex(q=>!answered(props.answers[q.id]))
const index=ref(typeof remembered==='number'?Math.min(remembered,props.questions.length-1):Math.max(0,firstUnanswered)), drawer=ref(false), confirm=ref(false), view=ref<'questions'|'feedback'>(props.submitted?'feedback':'questions')
const question=computed(()=>props.questions[index.value]), count=computed(()=>props.questions.filter(q=>answered(props.answers[q.id])).length), missing=computed(()=>props.questions.map((q,i)=>({q,i})).filter(x=>!answered(props.answers[x.q.id])))
const area=ref<HTMLElement|null>(null)
const types:Record<string,string>={single_choice:'单选题',multiple_choice:'多选题',true_false:'判断题',fill_blank:'填空题',short_answer:'简答题'}
function answer(value:string|string[]) { if(!question.value||props.submitted||props.busy)return;emit('update:answers',{...props.answers,[question.value.id]:value}) }
function toggle(option:string) { const value=props.answers[question.value!.id];const values=Array.isArray(value)?value:[];answer(values.includes(option)?values.filter(x=>x!==option):[...values,option]) }
function includes(option:string) {
  const value=props.answers[question.value!.id]
  if(Array.isArray(value))return value.includes(option)
  if(question.value?.question_type==='multiple_choice' && typeof value==='string') {
    try {const saved=JSON.parse(value);if(Array.isArray(saved))return saved.includes(option)}catch{/* Historical plain answers remain readable. */}
  }
  return value===option
}
async function go(value:number) {index.value=Math.max(0,Math.min(props.questions.length-1,value));drawer.value=false;view.value='questions';await nextTick();area.value?.scrollTo({top:0});area.value?.focus({preventScroll:true})}
watch(()=>props.submitted,value=>{confirm.value=false;if(value)view.value='feedback'})
onBeforeUnmount(()=>{memory?.values.set(memoryKey,index.value)})
</script>
<template>
  <section class="student-task-workspace" aria-label="作业作答工作区">
    <div class="task-progress-bar"><span>{{ submitted?'提交记录':`已作答 ${count} / ${questions.length} 题` }}</span><i aria-hidden="true"><b :style="{width:(questions.length?count/questions.length*100:0)+'%'}" /></i><button type="button" class="task-mobile-nav" :aria-expanded="drawer" @click="drawer=!drawer">题号 {{ index+1 }}/{{ questions.length }} ⌄</button><button v-if="submitted" type="button" @click="view=view==='feedback'?'questions':'feedback'">{{ view==='feedback'?'查看我的作答':'查看成绩与反馈' }}</button></div>
    <div class="task-workspace-body"><aside class="task-question-nav" :class="{expanded:drawer}" aria-label="题号导航"><header><strong>题目导航</strong><small>{{ submitted?'查看提交时的作答':'点击题号切换' }}</small></header><div><button v-for="(item,i) in questions" :key="item.id" type="button" :aria-label="`第${i+1}题，${answered(answers[item.id])?'已作答':'未作答'}`" :aria-current="view==='questions'&&index===i?'step':undefined" :class="{answered:answered(answers[item.id])}" @click="go(i)">{{ i+1 }}</button></div><p>● 已答 <span>○ 未答</span></p></aside>
      <main ref="area" class="task-question-body" tabindex="0" :aria-label="view==='feedback'?'作业反馈':`第${index+1}题内容`"><slot name="notice" /><template v-if="view==='feedback'"><slot name="feedback" /></template><template v-else-if="question"><header class="task-question-heading"><span>第 {{ index+1 }} 题 <small>/ {{ questions.length }}</small></span><b>{{ types[question.question_type] || question.question_type }}</b><small>{{ question.knowledge_point || '课程练习' }}</small></header><RichText :source="question.stem" :tools="false" />
      <fieldset v-if="question.options.length" class="task-answer-options" :disabled="submitted||busy"><legend class="task-visually-hidden">请选择答案</legend><label v-for="(option,i) in question.options" :key="option" :class="{chosen:includes(option)}"><input :type="question.question_type==='multiple_choice'?'checkbox':'radio'" :name="`task-${question.id}`" :checked="includes(option)" @change="question.question_type==='multiple_choice'?toggle(option):answer(option)" /><span class="task-option-marker">{{ String.fromCharCode(65+i) }}</span><span>{{ option }}</span></label></fieldset>
      <label v-else class="task-written-answer"><span>我的作答</span><textarea :value="answers[question.id] || ''" :disabled="submitted||busy" rows="8" :placeholder="question.question_type==='fill_blank'?'按顺序填写，多个空用 || 分隔':'写下你的答案和推导过程…'" @input="answer(($event.target as HTMLTextAreaElement).value)" /></label>
      <button v-if="aiPolicy!=='disabled'" type="button" class="task-assistant-button" :disabled="busy" @click="emit('assist',question.id)">✦ {{ aiPolicy==='guided'?'AI 分步辅导':'AI 思路提示' }}</button><small v-else>本作业需独立完成</small>
      <details v-if="submitted&&graded&&question.correct_answer" class="task-answer-explanation"><summary>查看参考答案与解析</summary><h4>参考答案</h4><RichText :source="question.correct_answer" :tools="false" /><template v-if="question.explanation"><h4>解析</h4><RichText :source="question.explanation" :tools="false" /></template></details></template><p v-else class="task-empty">本作业暂无题目，请联系任课教师。</p></main>
    </div>
    <p v-if="busy" class="task-save-message" role="status"><span class="ui-spinner" aria-hidden="true" /> 正在处理，请稍候…</p>
    <p v-else-if="message" class="task-save-message" role="status">{{ message }}</p>
    <footer class="task-runner-footer"><div><button type="button" :disabled="index<=0||busy" @click="go(index-1)">上一题</button><button type="button" :disabled="index>=questions.length-1||busy" @click="go(index+1)">下一题</button></div><button v-if="!submitted&&canSubmit" type="button" class="task-submit" :disabled="busy||!questions.length" @click="confirm=true">{{ busy?'正在提交…':'检查并提交' }}</button><span v-else-if="submitted">{{ graded?'已批改':'待教师批改' }}</span><span v-else>暂不可提交，查看补交安排</span></footer>
    <DetailDialog v-if="confirm" title="检查并提交作业" size="small" :close-disabled="busy" @close="confirm=false"><p>已作答 {{ count }} / {{ questions.length }} 题。提交后不能自行修改答案。</p><div v-if="missing.length" class="task-unanswered"><strong>还有 {{ missing.length }} 题未作答</strong><p>点击题号返回检查；也可以明确确认后按当前答案提交。</p><div><button v-for="item in missing" :key="item.q.id" type="button" @click="confirm=false;go(item.i)">第 {{ item.i+1 }} 题</button></div></div><p v-else>所有题目均已填写，请确认内容后提交。</p><template #footer><button type="button" :disabled="busy" @click="confirm=false">返回检查</button><button type="button" class="task-submit" :disabled="busy" @click="confirm=false;emit('submit')">确认提交</button></template></DetailDialog>
  </section>
</template>
<style scoped>
.student-task-workspace{display:flex;flex:1;flex-direction:column;min-height:0;color:#2c4769}.task-progress-bar{display:flex;gap:16px;align-items:center;padding:13px 24px;border-bottom:1px solid #e7edf5;flex:none;background:#f9fbfe;font-size:12px;color:#758da9}.task-progress-bar>span{flex:none}.task-progress-bar>i{height:5px;background:#e2eaf6;max-width:180px;width:100%;border-radius:5px;overflow:hidden}.task-progress-bar>i>b{display:block;background:#6795da;height:100%}.task-progress-bar>button{margin-left:auto}.task-workspace-body{display:flex;flex:1;min-height:0}.task-question-nav{width:170px;flex:none;padding:24px 18px;border-right:1px solid #e6edf5;background:#fbfcfe;overflow:auto}.task-question-nav header{display:grid;gap:8px;font-size:13px}.task-question-nav header small{font-size:11px;font-weight:400;color:#92a1b6}.task-question-nav>div{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin:22px 0}.task-question-nav button{padding:0;height:31px;background:white;border:1px solid #dce6f3;color:#8b9db5;border-radius:7px;font-size:12px}.task-question-nav button.answered{background:#eaf2ff;color:#3f75b9;border-color:#c4d8f4}.task-question-nav button[aria-current=step]{background:#3675c9;color:white;border-color:#3675c9}.task-question-nav>p{font-size:10px;color:#6c90c0;display:flex;gap:12px}.task-question-nav>p span{color:#93a4b8}.task-question-body{flex:1;min-width:0;min-height:0;overflow:auto;padding:30px 36px;outline:none;overscroll-behavior:contain}.task-question-heading{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin-bottom:24px;font-size:14px}.task-question-heading span{font-size:18px;font-weight:700}.task-question-heading span small{color:#99a9bd;font-size:12px;font-weight:400}.task-question-heading b{font-size:11px;background:#edf3fc;color:#567eae;padding:5px 8px;border-radius:6px}.task-question-heading>small{color:#8a9db5;font-size:11px}.task-answer-options{border:0;padding:0;margin:26px 0;display:grid;gap:12px;min-width:0}.task-answer-options label{display:flex;align-items:start;gap:14px;border:1px solid #dfe7f3;background:white;border-radius:12px;padding:16px;font-size:14px;line-height:1.8;cursor:pointer;font-weight:400;overflow-wrap:anywhere}.task-answer-options label.chosen{background:#f0f5ff;border-color:#83ace2}.task-answer-options input{accent-color:#3978ca;margin-top:6px;flex:none}.task-option-marker{width:25px;height:25px;border:1px solid #e0e8f4;border-radius:7px;display:grid;place-items:center;font-size:12px;color:#7093be;flex:none}.task-answer-options label>span:last-child{min-width:0}.task-written-answer{display:grid;gap:12px;font-size:12px;margin:24px 0;color:#7890ad}.task-written-answer textarea{resize:vertical;min-height:160px;background:#fcfdff;color:#294669;border:1px solid #d9e4f4;border-radius:12px;padding:17px;font:inherit;font-size:15px;line-height:1.9;max-width:100%;box-sizing:border-box}.task-answer-explanation{border:1px solid #dbe8f7;background:#f6faff;padding:17px;border-radius:12px;font-size:13px;line-height:1.8;margin-top:22px}.task-answer-explanation summary{cursor:pointer;color:#4479b9}.task-answer-explanation h4{font-size:12px;color:#6e89ac}.task-runner-footer{display:flex;flex:none;align-items:center;justify-content:space-between;gap:10px;padding:15px 24px;border-top:1px solid #e1e9f4;background:white}.task-runner-footer>div{display:flex;gap:8px}.task-runner-footer>span{font-size:11px;color:#8295ae}.task-runner-footer button,.task-progress-bar button,.task-unanswered button{background:#edf3fc;color:#5278a8;border:1px solid #dbe5f2;border-radius:9px;font-size:12px;padding:10px 15px}.task-submit{background:#3474c9!important;color:white!important;border-color:#3474c9!important}.task-mobile-nav{display:none}.task-save-message{font-size:12px;background:#f2f7ff;color:#547ba8;padding:10px 24px;margin:0;flex:none;line-height:1.7}.task-unanswered{padding:16px;background:#fff8ed;border-radius:12px;color:#a47a45;font-size:12px;line-height:1.8}.task-unanswered>div{display:flex;gap:7px;flex-wrap:wrap}.task-unanswered p{color:#9c8c75}.task-visually-hidden{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}button:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid #aac9ef;outline-offset:2px}button:disabled{opacity:.5}
@media(max-width:700px){.task-progress-bar{padding:11px 15px;gap:10px;font-size:11px}.task-progress-bar>i{max-width:80px}.task-mobile-nav{display:block}.task-workspace-body{position:relative}.task-question-nav{display:none}.task-question-nav.expanded{display:block;position:absolute;inset:0 0 auto;width:auto;max-height:70%;z-index:2;box-shadow:0 14px 20px #203c631a;border-bottom:1px solid #dfe9f5}.task-question-nav>div{grid-template-columns:repeat(7,minmax(0,1fr));margin:15px 0}.task-question-body{padding:20px 16px}.task-question-heading{gap:9px;margin-bottom:18px}.task-question-heading span{font-size:16px}.task-answer-options{gap:10px;margin:20px 0}.task-answer-options label{font-size:14px;padding:13px;gap:10px}.task-written-answer textarea{font-size:16px;padding:13px}.task-runner-footer{padding:12px 14px calc(12px + env(safe-area-inset-bottom));gap:6px}.task-runner-footer button{font-size:12px;padding:11px 12px}.task-runner-footer>div{gap:5px}.task-save-message{padding:8px 15px;font-size:11px}}
@media(max-height:500px){.task-question-heading{margin-bottom:10px}.task-question-body{padding-top:12px}.task-progress-bar{padding-top:7px;padding-bottom:7px}.task-runner-footer{padding-top:8px;padding-bottom:8px}}
</style>
